<?php if($prospect['archived_at']===null&&$prospect['status']==='qualified'):?><section class="settings-panel"><h2>Open opportunity</h2><p>Create a commercial pipeline record for this qualified prospect.</p><form method="post" action="<?= $escape($router->url('opportunities.create',['id'=>$prospect['id']])) ?>"><input type="hidden" name="_csrf" value="<?= $escape($csrfToken) ?>"><input type="hidden" name="prospect_version" value="<?= $escape($prospect['version']) ?>"><label>Offer<select name="offer_key"><option value="discovery">Discovery and technical assessment</option><option value="implementation">Implementation engagement</option><option value="retainer">Ongoing advisory retainer</option></select></label><label>Estimated value (USD)<input name="value_amount" value="0.00" required></label><label>Expected close<input type="date" name="expected_close_on"></label><?php if($followUp):?><label><input type="checkbox" name="attach_follow_up" value="1"> Associate the current next action</label><?php endif;?><button>Create opportunity</button></form></section><?php endif;?>
<?php if($prospect['archived_at']===null):?><section class="settings-panel"><h2>Next action</h2><?php $rescheduling=$followUp!==null;?><p><?= $rescheduling?'Reschedule the open action; its history is preserved.':'No next action is scheduled.' ?></p><form method="post" action="<?= $escape($rescheduling?$followUpRescheduleUrl((int)$followUp['id']):$followUpUrl) ?>"><input type="hidden" name="_csrf" value="<?= $escape($csrfToken) ?>"><input type="hidden" name="prospect_version" value="<?= $escape($prospect['version']) ?>"><?php if($rescheduling):?><input type="hidden" name="version" value="<?= $escape($followUp['version']) ?>"><?php endif;?><label>Action<input name="action" value="<?= $escape($followUp['action']??'') ?>" required></label><label>Due at<input type="datetime-local" name="due_at" required></label><button><?= $rescheduling?'Reschedule next action':'Schedule next action' ?></button></form></section><?php endif;?>
<header class="page-header"><div><p class="eyebrow"><?= $escape($segments[$prospect['segment']]??$prospect['segment']) ?></p><h1><?= $escape($prospect['company_name']?:trim(($prospect['first_name']??'').' '.($prospect['last_name']??''))) ?></h1><p>Status: <strong><?= $escape($statuses[$prospect['status']]??$prospect['status']) ?></strong></p></div><a class="button" href="<?= $escape($editUrl) ?>">Edit research</a></header><dl class="record-details"><div><dt>Contact</dt><dd><?= $escape(trim(($prospect['first_name']??'').' '.($prospect['last_name']??''))?:'—') ?></dd></div><div><dt>Source</dt><dd><?= $escape($prospect['source']??'—') ?></dd></div><div><dt>Why them?</dt><dd class="preserve-lines"><?= $escape($prospect['why_them']??'—') ?></dd></div><div><dt>Business problem</dt><dd class="preserve-lines"><?= $escape($prospect['business_problem']??'—') ?></dd></div></dl>
<?php if($prospect['archived_at']===null):?><section class="settings-panel"><h2>Change status</h2><?php if($allowed===[]):?><p>No ordinary transitions are available.</p><?php else:?><form method="post" action="<?= $escape($transitionUrl) ?>"><input type="hidden" name="_csrf" value="<?= $escape($csrfToken) ?>"><input type="hidden" name="version" value="<?= $escape($prospect['version']) ?>"><label>New status<select name="to_status"><?php foreach($allowed as $s):?><option value="<?= $escape($s) ?>"><?= $escape($statuses[$s]) ?></option><?php endforeach;?></select></label><label>Reason<textarea name="reason"></textarea></label><button>Change status</button></form><?php endif;?></section><?php endif;?>
<section><h2>Buying signals</h2><?php if($signals===[]):?><p>No signal evidence recorded.</p><?php else:?><ul><?php foreach($signals as $s):?><li><strong><?= $escape($s['name']) ?></strong><?php if($prospect['archived_at']===null):?><form method="post" action="<?= $escape($signalUpdateUrl((int)$s['id'])) ?>"><input type="hidden" name="_csrf" value="<?= $escape($csrfToken) ?>"><input type="hidden" name="version" value="<?= $escape($prospect['version']) ?>"><input type="hidden" name="signal_version" value="<?= $escape($s['version']) ?>"><label>Evidence<textarea name="evidence_note" required><?= $escape($s['evidence_note']) ?></textarea></label><label>Observed on<input type="date" name="observed_on" value="<?= $escape($s['observed_on']??'') ?>"></label><button type="submit">Update evidence</button></form><form class="inline-form" method="post" action="<?= $escape($signalRemoveUrl((int)$s['id'])) ?>"><input type="hidden" name="_csrf" value="<?= $escape($csrfToken) ?>"><input type="hidden" name="version" value="<?= $escape($prospect['version']) ?>"><input type="hidden" name="signal_version" value="<?= $escape($s['version']) ?>"><button type="submit">Remove</button></form><?php else:?>: <?= $escape($s['evidence_note']) ?><?php endif;?></li><?php endforeach;?></ul><?php endif;?><?php if($prospect['archived_at']===null):?><form method="post" action="<?= $escape($signalUrl) ?>"><input type="hidden" name="_csrf" value="<?= $escape($csrfToken) ?>"><input type="hidden" name="version" value="<?= $escape($prospect['version']) ?>"><label>Signal<select name="signal_id"><?php foreach($signalTypes as $s):?><option value="<?= $escape($s['id']) ?>"><?= $escape($s['name']) ?></option><?php endforeach;?></select></label><label>Evidence<textarea name="evidence_note" required></textarea></label><label>Observed on<input type="date" name="observed_on"></label><button>Add evidence</button></form><?php endif;?></section>
<section><h2>Status history</h2><?php $latestValidId=null;foreach($events as $candidate){if($candidate['voided_at']===null){$latestValidId=(int)$candidate['id'];break;}} ?><ol class="timeline"><?php foreach($events as $e):?><li<?= $e['voided_at']?' class="is-voided"':'' ?>><strong><?= $escape($statuses[$e['to_status']]??$e['to_status']) ?></strong> <time><?= $escape($e['occurred_at']) ?></time><?php if($e['reason']):?> — <?= $escape($e['reason']) ?><?php endif;?><?= $e['voided_at']?' (voided)':'' ?><?php if((int)$e['id']===$latestValidId&&($e['from_status']!==null||$prospect['archived_at']!==null)):?><form method="post" action="<?= $escape($eventVoidUrl((int)$e['id'])) ?>"><input type="hidden" name="_csrf" value="<?= $escape($csrfToken) ?>"><input type="hidden" name="version" value="<?= $escape($prospect['version']) ?>"><input type="hidden" name="event_version" value="<?= $escape($e['version']) ?>"><label>Correction reason<input name="void_reason" required></label><button type="submit">Void latest event</button></form><?php endif;?></li><?php endforeach;?></ol></section><form method="post" action="<?= $escape($archiveUrl) ?>"><input type="hidden" name="_csrf" value="<?= $escape($csrfToken) ?>"><input type="hidden" name="version" value="<?= $escape($prospect['version']) ?>"><button class="button button--danger"><?= $prospect['archived_at']?'Restore prospect':'Archive prospect' ?></button></form>
<section><h2>Interactions</h2><?php if($interactions===[]):?><p>No communication recorded yet.</p><?php else:?><ol class="timeline"><?php foreach($interactions as $interaction):?><li<?= $interaction['voided_at']?' class="is-voided"':'' ?>><strong><?= $escape($interactionTypes[$interaction['type']]??$interaction['type']) ?></strong> — <?= $escape($interactionOutcomes[$interaction['outcome']]['label']??$interaction['outcome']) ?><time><?= $escape($interaction['occurred_at']) ?></time><p><?= $escape($interaction['summary']) ?></p><?php if($interaction['voided_at']):?><p>Corrected: <?= $escape($interaction['voided_reason']) ?></p><?php endif;?></li><?php endforeach;?></ol><?php endif;?><?php if($prospect['archived_at']===null):?><form method="post" action="<?= $escape($interactionUrl) ?>"><input type="hidden" name="_csrf" value="<?= $escape($csrfToken) ?>"><input type="hidden" name="version" value="<?= $escape($prospect['version']) ?>"><label>Type<select name="type"><?php foreach($interactionTypes as $key=>$label):?><option value="<?= $escape($key) ?>"><?= $escape($label) ?></option><?php endforeach;?></select></label><label>Direction<select name="direction"><?php foreach($interactionDirections as $key=>$label):?><option value="<?= $escape($key) ?>"><?= $escape($label) ?></option><?php endforeach;?></select></label><label>Outcome<select name="outcome"><?php foreach($interactionOutcomes as $key=>$rule):?><option value="<?= $escape($key) ?>"><?= $escape($rule['label']) ?></option><?php endforeach;?></select></label><label>Occurred at<input type="datetime-local" name="occurred_at" required></label><label>Summary<textarea name="summary" required></textarea></label><button>Record interaction</button></form><?php endif;?></section>
